mapper.select:
SELECT COUNT(1) AS "CNT"
FROM   MSTAP
WHERE  APLCOD = #{APLCOD}

SELECT PTNRKY AS "PTNRKY"
   ,   NAME01 AS "NAME01"
FROM   BZPTN 
WHERE  COMPKY = #{COMPID}
AND    PTNRKY = #{PTNRKY}

SELECT SKUKEY AS "SKUKEY"
   ,   DESC01 AS "DESC01"
   ,   DUOMKY AS "UOMKEY"
FROM   SKUMA 
WHERE  COMPKY = #{COMPID}
AND    SKUKEY = #{SKUKEY}

SELECT COUNT(1) AS "CNT"
FROM   SHPDH A   
       INNER JOIN SHPDI B ON  A.COMPKY = B.COMPKY
	                      AND A.SHPOKY = B.SHPOKY
WHERE  A.COMPKY = #{COMPID}
AND    A.SHPOKY = #{SHPOKY}
AND    B.SHPOIT = #{SHPOIT}
AND    A.STATDO IN('FSH','PSH')

SELECT B.SEBELN AS "SEBELN" , B.SEBELP AS "SEBELP" , CASE WHEN B.QTYRCV = 0 AND COALESCE(C.QTYDIF, 0) = 0 THEN '미작업' WHEN (B.QTYASN - B.QTYRCV) = 0 AND COALESCE(C.QTYDIF, 0) = 0 THEN '입고완료' WHEN (B.QTYASN - B.QTYRCV) > 0 AND COALESCE(C.QTYDIF, 0) = 0 THEN '부분입고' WHEN COALESCE(C.QTYDIF, 0) > 0 AND (B.QTYASN - COALESCE(C.QTYDIF, 0)) = 0 THEN '적치완료' WHEN COALESCE(C.QTYDIF, 0) > 0 AND (B.QTYASN - COALESCE(C.QTYDIF, 0)) > 0 THEN '부분적치' END AS "STATIT" , B.LOTA04 AS "LOTA04" , B.LOTA05 AS "LOTA05" , A.DOCDAT AS "DOCDAT" , B.SKUKEY AS "SKUKEY" , B.DESC01 AS "DESC01" , B.QTYASN::INT AS "QTYASN" , B.QTYRCV::INT AS "QTYRCV" , COALESCE(C.QTYDIF::INT, 0) AS "QTYTSK" , B.UOMKEY AS "UOMKEY" , B.LOTA02 AS "LOTA02" , B.LOTA03 AS "LOTA03" FROM ASNDH A INNER JOIN ASNDI B ON A.COMPKY = B.COMPKY AND A.ASNDKY = B.ASNDKY LEFT OUTER JOIN RECDI C ON B.COMPKY = C.COMPKY AND B.ASNDKY = C.REFDKY AND B.ASNDIT = C.REFDIT WHERE A.COMPKY = #{COMPID} AND A.ASNTTY = #{ASNTTY}
AND A.DOCDAT BETWEEN #{STRDAT} AND #{ENDDAT}
AND A.DOCDAT = #{STRDAT}
AND A.DOCDAT = #{ENDDAT}
AND B.SEBELN = #{SEBELN}
AND B.SEBELP = #{SEBELP}
ORDER BY B.SEBELN, B.SEBELP

SELECT A.SVBELN AS "SVBELN" , A.SPOSNR AS "SPOSNR" , CASE WHEN SHPOKY = '' THEN 'WAVE 생성 전' WHEN QTALOC = 0 THEN '미작업' WHEN QTALOC > 0 AND (QTYORD - QTALOC) = 0 AND QTJCMP = 0 AND QTSHPD = 0 THEN '할당완료' WHEN QTALOC > 0 AND (QTYORD - QTALOC) > 0 AND QTJCMP = 0 AND QTSHPD = 0 THEN '부분할당' WHEN (QTALOC > 0 AND QTJCMP > 0) AND (QTYORD - QTJCMP) = 0 AND QTSHPD = 0 THEN '피킹완료' WHEN (QTALOC > 0 AND QTJCMP > 0) AND (QTYORD - QTJCMP) > 0 AND QTSHPD = 0 THEN '부분피킹' WHEN (QTALOC > 0 AND QTJCMP > 0 AND QTSHPD > 0) AND (QTYORD - QTSHPD) = 0 THEN '출고완료' WHEN (QTALOC > 0 AND QTJCMP > 0 AND QTSHPD > 0) AND (QTYORD - QTSHPD) > 0 THEN '부분출고' END AS "STATDO" , A.RQSHPD AS "RQSHPD" , A.PTNRKY AS "PTNRKY" , A.PTNRNM AS "PTNRNM" , A.PTRCVR AS "PTRCVR" , A.PTRCNM AS "PTRCNM" , A.SKUKEY AS "SKUKEY" , A.DESC01 AS "DESC01" , A.QTYORD AS "QTYORD" , A.QTALOC AS "QTALOC" , A.QTJCMP AS "QTJCMP" , A.QTSHPD AS "QTSHPD" , A.SHPOKY AS "SHPOKY" , A.SHPOIT AS "SHPOIT" FROM( SELECT A.SVBELN , A.SPOSNR , A.RQSHPD , A.PTNRKY , A.PTNRNM , A.PTRCVR , A.PTRCNM , A.SKUKEY , A.DESC01 , A.QTYORD :: INT , COALESCE(B.QTALOC :: INT, 0) AS QTALOC , COALESCE(B.QTJCMP :: INT, 0) AS QTJCMP , COALESCE(B.QTSHPD :: INT, 0) AS QTSHPD , COALESCE(B.SHPOKY,'') AS SHPOKY , COALESCE(B.SHPOIT,'') AS SHPOIT FROM IFSHP A LEFT OUTER JOIN SHPDI B ON A.COMPKY = B.COMPKY AND A.SVBELN = B.SVBELN AND A.SPOSNR = B.SPOSNR WHERE A.COMPKY = #{COMPID}
AND A.RQSHPD BETWEEN #{STRDAT} AND #{ENDDAT}
AND A.RQSHPD = #{STRDAT}
AND A.RQSHPD = #{ENDDAT}
AND A.SVBELN = #{SVBELN}
AND A.SPOSNR = #{SPOSNR}
) A ORDER BY A.SVBELN, A.SPOSNR
